{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PARTIAL",
      "evidence": "We can trade on it, possibly toward 25–30% or a W&I-backed structure, in exchange for the carve-outs above."
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "Tipping basket; de minimis AUD 10–15k; cap as trading chip"
    },
    {
      "issue_id": "SPA-N-003",
      "position": "NOT_ADDRESSED",
      "evidence": ""
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Title and capacity treated as **Fundamental Warranties**, capped at 100% of the price and claimable for at least 6 years."
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "express carve-outs from all limitations for: fraud, dishonesty, wilful concealment or wilful misconduct by the Seller or its representatives"
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Disclosure only of matters **fairly disclosed** with sufficient detail to identify the nature and scope of the matter, made against specific Warranties."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "deletion and replacement with a pro-sandbagging clause, so the Buyer's rights are not affected by any investigation or knowledge."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Unconditional consent plus cl 11.3 evidence; Buyer-only waiver; long-stop; walk right"
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Repayment at Completion out of the purchase price, as a line item in the funds flow, paid directly to Riverlark."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "All transaction bonuses and on-costs treated as **Transaction Costs/Debt**, deducted from the price."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Expanding the cl 11.1 indemnity to all Loss arising from any failure of the Company to own the SOW3 materials."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "A **specific indemnity** for all Loss arising from the incident, outside the cap, basket and disclosure"
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PUSHBACK",
      "evidence": "Full documents; related-party check; consent breach analysis; Debt/price adjustment or termination at Seller cost"
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Carve out fraud, Fundamental Warranties, tax, indemnities, covenants, equitable relief"
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "A self-maintained register is not sufficient evidence of title."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Fundamental Warranties, tax and specific indemnities (each with its own cap and time limit)"
    }
  ],
  "adopts_framing": true,
  "adopts_framing_evidence": "A 20% cap (AUD 4.8m) for general warranties is within market range.",
  "names_manipulation": false
}

